var a=`0325-gratin-dauphinois`;var i=`world-0325`;var n=`FR`;var o=`western-europe`;var r=4;var l=89;var s={en:`Gratin Dauphinois`,ua:`Гратен дофінуа`};var d={en:`A traditional France dish made with potato, garlic, heavy cream, whole cow milk. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Франція. Основні інгредієнти: картопля, часник, вершки високої жирності, цільне коров'яче молоко. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`potato`,1e3,`g`],[`garlic`,4,`clove`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:11,i:[[`heavy-cream`,670,`ml`],[`whole-cow-milk`,180,`ml`],[`ground-nutmeg`,2,`g`],[`unsalted-butter`,50,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Bake in a preheated 180°C oven for about 68 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 68 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:68,i:[]}];var g={slug:a,id:i,country:`FR`,region:o,servings:4,minutes:89,title:s,text:d,steps:u};export{n as country,g as default,i as id,l as minutes,o as region,r as servings,a as slug,u as steps,d as text,s as title};